                i = rest.index('/')
                inst.nets = rest[:i]
                after = rest[i + 1:]
                inst.master = after[0] if after else ''
            else:
                inst.nets, inst.master = split_x_no_slash(rest, ci_index)
        elif letter == 'M':
            # drain gate source bulk model [params...]
            inst.nets = rest[:4]
            if len(rest) > 4:
                inst.master = rest[4]
        else:
            # two-terminal device (R/C/V/I/L/D/B ...): n1 n2 ...
            inst.nets = rest[:2]

